F("קרטינג ומוטורספורט", "אינדור קרטינג ברצלונה", "Indoor Karting Barcelona", 41.39484, 2.03424, OUT,
  "מסלול קרטינג מקורה בסנט פליו דה יוברגט, כ-20 דקות נסיעה ממערב לברצלונה. מכיוון שהמסלול תחת גג, הפעילות אינה תלויה במזג האוויר ומתאימה גם ליום גשום או לערב. מתאים לקבוצות חברים, לבני נוער ולמשפחות עם ילדים שעומדים בדרישות הגובה.",
  "שעות הפעילות משתנות בין ימי חול לסופי שבוע. כדאי לבדוק באתר המקום.",
  "התשלום לפי מקצה נסיעה. המחירים באתר המקום.",
  "כדאי להזמין מראש, בעיקר לקבוצות ובסופי שבוע. לבוא בנעליים סגורות; קסדה מקבלים בדרך כלל במקום. דרישות גיל וגובה לילדים מפורטות באתר. " + SAFE + ". מגיעים ברכב או במונית, כ-20 דקות ממרכז העיר; בתחבורה ציבורית כדאי לבדוק מסלול מראש.",
  7.0, "Indoor Karting Barcelona Sant Feliu",
  "ריח גומי, זמזום מנועים ולוח תוצאות שמתעדכן בכל הקפה: קרטינג מקורה הוא הדרך הנגישה ביותר לטעום משהו ממרוצי המכוניות. במדינה שגידלה נהגי פורמולה 1 ורוכבי אופנועים אלופי עולם, מסלולי קרטינג הם חלק מהנוף, ורבים מהנהגים המקצועיים התחילו בדיוק כך, בגיל צעיר מאוד ובמכונית קטנה בלי גג.\n"
  "אינדור קרטינג ברצלונה פועל בסנט פליו דה יוברגט, על הדרך הראשית שיוצאת מהעיר מערבה. הפעילות בנויה בדרך כלל ממקצים קצובים בזמן: תדריך בטיחות קצר, קסדה, כמה דקות של נסיעה, ובסופן דף עם זמני ההקפה של כל נהג.",
  "פרטים כמו אורך המסלול, סוגי המכוניות, משך המקצה והגיל המינימלי אינם ידועים בוודאות ומופיעים באתר המקום. במסלולים מסוג זה יש בדרך כלל מכוניות נפרדות לילדים ומקצים נפרדים להם, וקבוצות יכולות להזמין מרוץ פרטי עם דירוג וחלוקת מקומות.",
  ["המסלול מקורה, ולכן הפעילות בו אינה תלויה בגשם."],
  kd="קרטינג", ag="8-25"),

F("קרטינג ומוטורספורט", "קרטינג קרדדאו", "Karting Cardedeu", 41.63392, 2.33748, OUT,
  "מסלול קרטינג פתוח ליד העיירה קרדדאו, כ-40 דקות נסיעה מצפון־מזרח לברצלונה. נוסעים באוויר הפתוח, על אספלט, מול נוף של גבעות. מתאים למי שמחפש חוויית נהיגה של ממש ומוכן לנסוע בשבילה אל מחוץ לעיר, ובכלל זה משפחות עם ילדים שעומדים בדרישות המקום.",
  "שעות הפעילות משתנות לפי עונה ומזג אוויר. כדאי לבדוק באתר המקום.",
  "התשלום לפי מקצה נסיעה וסוג המכונית. המחירים באתר המקום.",
  "כדאי להזמין מראש ולוודא שהמסלול פתוח, כי במסלול חיצוני גשם ואירועים פרטיים עלולים לשבש. לבוא בנעליים סגורות ובבגדים שמתאימים לעונה. " + SAFE + ". מגיעים בעיקר ברכב, כ-40 דקות ממרכז העיר; לקרדדאו יש גם רכבת פרברים (רודאליאס), וממנה ממשיכים במונית.",
  6.2, "Karting Cardedeu",
  "מי שנוהג בקרטינג מקורה ואחר כך יוצא למסלול פתוח מרגיש מיד את ההבדל: הישורות ארוכות יותר, הפניות רחבות, והרוח והשמש הופכות לחלק מהנסיעה. באזור ואייס אוריינטל, מעבר להרים שסוגרים את ברצלונה, הספורט המוטורי הוא עניין מקומי רציני, ומסלול הפורמולה 1 של מונטמלו נמצא לא הרחק.\n"
  "קרטינג קרדדאו פועל בשולי העיירה קרדדאו, על הדרך שבין ברצלונה לרכס מונטסני. כמו במסלולים דומים, הנהגים מקבלים תדריך וקסדה, יוצאים למקצה קצוב בזמן, ובסופו מקבלים את זמני ההקפה שלהם. מסלולים פתוחים משמשים לעתים קרובות גם נהגים עם מכוניות פרטיות ואימוני מועדונים.",
  "אורך המסלול, סוגי המכוניות וגיל המינימום אינם ידועים בוודאות, והם מפורטים באתר המקום. אפשר לשלב את הנסיעה עם ביקור במסלול ברצלונה־קטלוניה שבמונטמלו או עם טיול בפארק הטבע מונטסני. בקיץ כדאי לבחור בשעות הבוקר או הערב, כי על האספלט חם מאוד בצהריים.",
  ["המסלול פתוח לשמיים, ולכן כדאי לבדוק את התחזית לפני הנסיעה."],
  kd="קרטינג", ag="8-25"),

F("קרטינג ומוטורספורט", "מסלול ברצלונה־קטלוניה", "Circuit de Barcelona-Catalunya", 41.5700, 2.2611, OUT,
  "מסלול המרוצים של מונטמלו, כחצי שעה מברצלונה, שמארח מאז תחילת שנות התשעים מרוצי פורמולה 1 ו-MotoGP. בימי מרוץ זהו אירוע של עשרות אלפי צופים; בשאר השנה מתקיימים בו, לפי המתפרסם, סיורים מודרכים, ימי מסלול וחוויות נהיגה. מתאים לחובבי ספורט מוטורי.",
  "אין שעות קבועות למבקרים: הכול תלוי בלוח האירועים. סיורים וחוויות נהיגה בתיאום מראש בלבד. כדאי לבדוק באתר המקום.",
  "כרטיסים למרוצים, סיורים וחוויות נהיגה נמכרים בנפרד ובטווח מחירים רחב. המחירים באתר המקום.",
  "כדאי לבדוק קודם כול את לוח האירועים, כי בלי אירוע או סיור מתואם אין בדרך כלל כניסה. מגיעים ברכבת פרברים (רודאליאס) בקו R2 לתחנת Montmeló, וממנה הליכה של כחצי שעה או הסעה בימי מרוץ. בימי מרוץ כדאי להביא כובע, מים ואטמי אוזניים. המזון שנמכר במתחם אינו כשר. לחוויות נהיגה: " + SAFE + ".",
  7.5, "Circuit de Barcelona-Catalunya Montmeló",
  "ביום ראשון של מרוץ, העיירה מונטמלו משנה את פניה. הרכבות מברצלונה מגיעות מלאות באוהדים בחולצות אדומות, כתומות וכסופות, והשביל מהתחנה אל המסלול הופך לתהלוכה ארוכה. המסלול נחנך ב-1991, שנה לפני המשחקים האולימפיים של ברצלונה, ומאותה שנה אירח במשך יותר משלושה עשורים את הגרנד פרי של ספרד בפורמולה 1. במהלך שנות התשעים נוספו אליו מרוצי אליפות העולם באופנועים, ובהם הגרנד פרי של קטלוניה.\n"
  "אורכו כ-4.7 קילומטרים, עם ישורת פתיחה ארוכה ורצף של פניות מהירות ואיטיות. בשל האקלים הנוח והמגוון הזה שימש המסלול במשך שנים רבות גם לאימוני החורף של קבוצות הפורמולה 1, ולכן נהגים ומהנדסים מכירים אותו היטב. עבור הקהל הספרדי הוא קשור במיוחד לשמותיהם של נהגי ורוכבי הבית.",
  "מעמדו של מרוץ הפורמולה 1 במונטמלו השתנה בשנים האחרונות. לפי המתפרסם, התואר הגרנד פרי של ספרד עבר החל מ-2026 למרוץ חדש במדריד, ואילו המרוץ במונטמלו אמור להמשיך בשם אחר, וייתכן שלא בכל שנה. הפרטים עשויים להשתנות, ולכן כדאי לבדוק את לוח המרוצים העדכני לפני שמתכננים נסיעה סביב אירוע. מרוצי האופנועים, מרוצי סיבולת וימי מסלול ממלאים את רוב השנה, והסיורים המודרכים כוללים בדרך כלל את מגדל הבקרה, הפודיום והמוסכים.",
  ["המסלול נחנך בספטמבר 1991, ועוד באותו חודש נערך בו מרוץ פורמולה 1 ראשון."]),

# ---------- פיינטבול ולייזר טאג ----------
F("פיינטבול ולייזר טאג", "פליי פוינט, לייזר טאג ומציאות מדומה", "Play Point Laser Tag", 41.3801, 2.1593, EIX,
  "מרכז משחק מקורה ברחוב קומטה בורל, באזור סנט אנטוני, שמציע לפי תיאורו לייזר טאג, משחקי מציאות מדומה ופיינטבול מקורה. הכול במקום אחד ובמרחק הליכה ממרכז העיר, כך שזו אפשרות נוחה ליום גשום או לערב. מתאים למשפחות, לבני נוער ולקבוצות חברים.",
  "שעות הפעילות אינן ידועות בוודאות, ולרוב המשחקים בתיאום מראש. כדאי לבדוק באתר המקום.",
  "התשלום לפי משחק ומספר משתתפים. המחירים באתר המקום.",
  "כדאי להזמין מראש ולציין את גיל המשתתפים, כי לכל פעילות גיל מינימום משלה, ולפיינטבול הוא בדרך כלל גבוה יותר. לבוא בבגדים נוחים ובנעליים סגורות. לפיינטבול: " + SAFE + ". מטרו L2 סנט אנטוני, כמה דקות הליכה.",
  6.5, "Play Point Laser Tag Barcelona",
  "האור כבוי, מוזיקה מתנגנת, ומאחורי כל מחיצה עשוי להסתתר יריב עם אפוד מהבהב. לייזר טאג הוא גלגול ידידותי של משחקי התופסת והמחבואים: כל שחקן לובש אפוד עם חיישנים ומחזיק רובה שיורה קרן אור בלתי מזיקה, והמחשב סופר פגיעות. אין כאב ואין צבע, ולכן המשחק מתאים גם לילדים צעירים יחסית ולקבוצות מעורבות של הורים וילדים.\n"
  "פליי פוינט פועל ברחוב קומטה בורל, בחלק של אשמפלה שסמוך לשוק סנט אנטוני. לצד הלייזר טאג המקום מציע, לפי תיאורו, משחקי מציאות מדומה עם משקפיים, וכן פיינטבול מקורה, גרסה אינטנסיבית יותר, שמיועדת בדרך כלל למשתתפים מבוגרים יותר ודורשת ציוד מגן.",
  "פרטים כמו גודל הזירה, משך המשחק, מספר המשתתפים המרבי וגילי המינימום מופיעים באתר המקום. במרכזים מסוג זה משחק נמשך בדרך כלל רבע שעה עד עשרים דקות, ומקובל להזמין שניים או שלושה משחקים ברצף. מקומות כאלה פופולריים לימי הולדת, ולכן בסופי שבוע כדאי לתאם מראש.",
  ["בלייזר טאג יורים קרן אור, והאפוד רוטט או מהבהב כשנפגעים."],
  kd="לייזר טאג", ag="7-25"),

F("פיינטבול ולייזר טאג", "פיינטבול ברצלונה", "Paintball Barcelona", 41.40511, 1.97847, OUT,
  "שדה פיינטבול פתוח בשטח מיוער ממערב לברצלונה, כחצי שעה נסיעה מהעיר. משחקים בקבוצות, בין עצים, מחסות ומכשולים, עם מסכת מגן ורובה אוויר שיורה כדורי צבע. הפעילות מיועדת לקבוצות מאורגנות בהזמנה מראש, ומתאימה לבני נוער ולמבוגרים.",
  "אין שעות קבועות: המשחקים מתקיימים בתיאום מראש, לרוב בסופי שבוע. כדאי לבדוק מול המפעיל.",
  "התשלום לפי משתתף וכמות כדורי הצבע. המחירים אצל המפעיל.",
  "להזמין מראש, בדרך כלל לקבוצה במספר משתתפים מינימלי. ללבוש בגדים ארוכים וישנים ונעלי שטח, ולהביא בגדים להחלפה. גיל המינימום נקבע בידי המפעיל. " + SAFE + ". מגיעים ברכב, כחצי שעה ממרכז העיר; אין תחבורה ציבורית נוחה עד השדה.",
  6.0, "Paintball Barcelona",
  "כדור צבע פוגע במגן עץ ומשאיר כתם צהוב, ומאחורי המגן מישהו עוצר את הנשימה. פיינטבול נולד בארצות הברית בתחילת שנות השמונים, כשכמה חברים החליטו לשחק זה מול זה ברובים ששימשו עד אז לסימון עצים ובקר. מאז הפך למשחק קבוצתי נפוץ בכל העולם, ובספרד הוא פעילות מקובלת למסיבות רווקים, לימי גיבוש ולימי הולדת של בני נוער.\n"
  "השדה שנושא את השם פיינטבול ברצלונה נמצא בגבעות המיוערות שממערב לעיר, מעבר לנהר יוברגט. המשחק מתנהל בדרך כלל בסבבים קצרים עם משימות מתחלפות, כמו תפיסת דגל או הגנה על עמדה, ובין סבב לסבב נחים וממלאים כדורים.",
  "המידע על המקום מוגבל, ולכן פרטים כמו מספר המגרשים, הציוד הכלול במחיר וגיל המינימום כדאי לברר ישירות מול המפעיל לפני ההזמנה. הפגיעה של כדור צבע מורגשת ועלולה להשאיר סימן, ולכן לבוש ארוך ושמירה על כללי המסכה חשובים. מי שמחפש גרסה עדינה יותר, או פעילות לילדים צעירים, ימצא אותה בלייזר טאג שבתוך העיר.",
  ["הרובים הראשונים של פיינטבול נועדו במקור לסימון עצים ובקר מרחוק."]),

