F("ארקייד", "ספייס אילוסיונה, דיאגונל מאר", "Space Ilusiona (Diagonal Mar)", 41.40992, 2.21521, SM,
  "מתחם משחקים בקומה הראשונה של קניון דיאגונל מאר, ליד הפורום והחוף. לפי המידע על המקום יש בו מכונות משחק, באולינג ומשחקים נוספים למשפחה. פתרון נוח ליום גשום, לשעת צהריים חמה או להפסקה מקניות. מתאים בעיקר לילדים ולבני נוער.",
  "בדרך כלל בשעות הקניון ומעט אחריהן. כדאי לבדוק באתר המקום.",
  "הכניסה חופשית והתשלום לפי משחק, לרוב באמצעות כרטיס נטען. המחירים באתר המקום.",
  "אין צורך בהזמנה לביקור רגיל; לבאולינג בסוף השבוע כדאי לבדוק זמינות. מומלץ לקבוע מראש עם הילדים סכום לטעינה. מזון ומשקאות שנמכרים במתחם אינם כשרים. מטרו L4 אל מרזמה־פורום, כמה דקות הליכה.",
  6.5, "Space Ilusiona Diagonal Mar Barcelona",
  "אורות מהבהבים, צלצולים, וכרטיסי פרסים שנפלטים מהמכונה: אולם משחקים נראה פחות או יותר אותו דבר בכל מקום בעולם, וזה חלק מהקסם שלו בעיני ילדים. אילוסיונה היא רשת ספרדית של מתחמי בילוי משפחתיים שפועלת בקניונים ברחבי המדינה, והסניף בדיאגונל מאר הוא הנוח ביותר למי שמתארח באזור החופים של סנט מרטי.\n"
  "הקניון עצמו נפתח בתחילת שנות האלפיים, בקצה שדרת דיאגונל, כחלק מהשכונה החדשה שנבנתה סביב הפורום. המתחם שוכן בקומה הראשונה, ולפי המידע עליו משלב מכונות ארקייד, מסלולי באולינג ומשחקי מיומנות שמזכים בנקודות לפרסים.",
  "מבחר המכונות מתחלף, ולכן לא מפורטים כאן משחקים מסוימים; בדרך כלל יש במתחמים כאלה סימולטורים של נהיגה, הוקי אוויר, קליעה לסל ומכונות לקטנים. כדאי לבדוק באתר המקום אם יש מבצעים לשעות מסוימות. אחרי המשחקים אפשר לצאת אל פארק דיאגונל מאר הסמוך או לרדת לחוף.",
  ["קניון דיאגונל מאר נבנה סמוך למתחם הפורום, שהוקם לקראת אירועי 2004."],
  kd="אולם משחקים", ag="5-18",
  kids="כאן מחליפים כסף בכרטיס קסם, וכל משחק מוציא כרטיסים קטנים שאפשר להמיר בפרס. נסו את הוקי האוויר נגד אבא או אמא, ובדקו מי קולע יותר סלים בדקה. טיפ: מחליטים מראש כמה משחקים, ואז בוחרים רק את הכי שווים."),

F("ארקייד", "אילוסיונה, גראן ויה 2", "Ilusiona Gran Via 2", 41.35802, 2.12887, EDGE,
  "מתחם משחקים ובאולינג בקניון גראן ויה 2, בל'אוספיטלט דה יוברגט, על הדרך בין ברצלונה לנמל התעופה. מכונות משחק לילדים ולבני נוער לצד מסלולי באולינג למשפחה כולה. נוח בעיקר למי שמתארח בדרום העיר או באזור מרכז הירידים, וליום שבו מזג האוויר אינו מאפשר חוף.",
  "בדרך כלל בשעות הקניון ומעט אחריהן. כדאי לבדוק באתר המקום.",
  "הכניסה חופשית והתשלום לפי משחק או לפי סבב באולינג. המחירים באתר המקום.",
  "לבאולינג בסופי שבוע כדאי לבדוק זמינות מראש. נעלי באולינג מקבלים במקום, ולכן כדאי לבוא בגרביים. מזון ומשקאות שנמכרים במתחם אינם כשרים. מגיעים ב-FGC (קו L8) לתחנת אילדפונס סרדה, כמה דקות הליכה; כדאי לוודא מסלול.",
  6.0, "Ilusiona Gran Via 2 Hospitalet Barcelona",
  "ל'אוספיטלט דה יוברגט היא עיר בפני עצמה, השנייה בגודלה בקטלוניה, אף שמי שנוסע בגראן ויה אינו מרגיש היכן ברצלונה נגמרת והיא מתחילה. בחלקה הדרומי, סביב כיכר אירופה ומתחם הירידים, קמו בשני העשורים האחרונים מגדלי משרדים, מלונות וקניון גדול, גראן ויה 2, שמשרת את תושבי הסביבה ואת באי התערוכות.\n"
  "בתוך הקניון פועל סניף של אילוסיונה, רשת ספרדית של מתחמי בילוי למשפחות. לפי המידע על המקום יש בו אולם ארקייד ואולם באולינג באותו מתחם, שילוב שמאפשר לחלק את הזמן בין משחק משותף לכל המשפחה לבין זמן חופשי של הילדים בין המכונות.",
  "מספר המסלולים ומבחר המכונות אינם ידועים בוודאות ומופיעים באתר המקום. במתחמים של הרשת משלמים בדרך כלל בכרטיס נטען, והנקודות שנצברות במשחקי המיומנות מומרות בפרסים קטנים. מי שמגיע לקניון ממילא, לקניות או לקולנוע, ימצא כאן תעסוקה של שעה או שעתיים לילדים.",
  ["ל'אוספיטלט דה יוברגט היא העיר השנייה בגודלה בקטלוניה מבחינת מספר התושבים."],
  kd="אולם משחקים", ag="5-18"),

# ---------- באולינג ----------
F("באולינג", "באולינג פדרלבס", "Bowling Pedralbes", 41.38064, 2.11677, TIB,
  "אולם באולינג ותיק באזור האוניברסיטה, כמה דקות הליכה מקאמפ נואו. פתוח מהבוקר ועד אחרי חצות, ובסופי שבוע עד מאוחר יותר, כך שהוא מתאים גם לבוקר עם ילדים וגם לבילוי לילי. מתאים למשפחות, לקבוצות חברים ולמי שמחפש פעילות אחרי סיור באצטדיון.",
  "בערך 10:00-24:00 בימים ראשון עד חמישי, ובשישי ובשבת עד 02:00. כדאי לבדוק באתר המקום.",
  "התשלום לפי משחק לאדם, והמחיר משתנה בדרך כלל לפי שעה ויום. המחירים באתר המקום.",
  "בערבי סוף השבוע כדאי להזמין מסלול מראש; בבקרים ובצהרי ימי חול רגוע יותר בדרך כלל. נעליים מקבלים במקום, כדאי לבוא בגרביים. המזון והמשקאות בבר המקום אינם כשרים. מטרו L3 פלאו ריאל, כעשר דקות הליכה; כדאי לוודא מסלול.",
  6.8, "Bowling Pedralbes Barcelona",
  "רעש הכדור שמתגלגל על העץ ונפץ הפינים בקצה המסלול הם פסקול שלא השתנה הרבה בחמישים השנים האחרונות. באולינג פדרלבס הוא מהאולמות הוותיקים והמוכרים בברצלונה, מקום שדורות של תושבי העיר חגגו בו ימי הולדת, נפגשו בו עם חברים מהאוניברסיטה הסמוכה או סיימו בו ערב אחרי משחק של בארסה.\n"
  "האולם נמצא בחלק העליון של רובע לס קורטס, בין הקמפוס האוניברסיטאי לאצטדיון. שעות הפתיחה הארוכות הן אחד המאפיינים שלו: בבוקר מגיעות בדרך כלל משפחות וקבוצות ילדים, ובלילות סוף השבוע הקהל לרוב מבוגר יותר.",
  "לצד המסלולים יש במקום בר, ובדרך כלל גם שולחנות ביליארד ומשחקים נוספים; מספר המסלולים והמחירים המדויקים מופיעים באתר המקום. לילדים קטנים יש באולמות באולינג לרוב כדורים קלים ומעקות צד שמונעים מהכדור ליפול לתעלה, כדאי לבקש אותם בקופה. אפשר לשלב את המשחק עם ביקור במוזיאון של בארסה או במנזר פדרלבס.",
  ["האולם פתוח בסופי שבוע עד שתיים בלילה, לפי השעות המפורסמות."],
  kd="באולינג", ag="6-25"),

F("באולינג", "ניו פארק באולינג, לה מקיניסטה", "New Park Bowling (La Maquinista)", 41.44022, 2.19916, EDGE,
  "אולם באולינג ומשחקים בקניון הפתוח לה מקיניסטה, ברובע סנט אנדראו שבצפון־מזרח ברצלונה. באולינג לכל המשפחה ומכונות משחק לילדים, בתוך מתחם קניות גדול עם קולנוע. מתאים למשפחות ולבני נוער, בעיקר כחלק מיום קניות או כפעילות ליום גשום.",
  "בדרך כלל מהצהריים ועד הלילה, ובסופי שבוע עד מאוחר יותר. כדאי לבדוק באתר המקום.",
  "התשלום לפי משחק לאדם, ולמכונות המשחק בנפרד. המחירים באתר המקום.",
  "בסופי שבוע כדאי לבדוק זמינות מסלולים מראש. נעלי באולינג מקבלים במקום. מזון ומשקאות שנמכרים באולם אינם כשרים. מטרו L1 לתחנת טוראס אי באז'ס או סנט אנדראו, ומשם כעשר דקות הליכה; כדאי לוודא מסלול.",
  6.3, "New Park Bowling La Maquinista Barcelona",
  "השם לה מקיניסטה אינו המצאה של אנשי שיווק. במקום שבו עומד היום הקניון פעל במשך רוב המאה ה-20 מפעל של לה מקיניסטה טרסטרה אי מריטימה, חברת המתכת וההנדסה הגדולה של ברצלונה, שבנתה קטרים, מנועים וגשרים לכל ספרד. כשהמפעל נסגר, הוקם על שטחו קניון באוויר הפתוח, מהגדולים בקטלוניה, והשם נשמר.\n"
  "בין החנויות, בתי הקפה ואולמות הקולנוע פועל ניו פארק באולינג, אולם בילוי משפחתי. הרעיון פשוט: מסלולי באולינג, ולצדם אזור של מכונות משחק שמעסיק את הילדים לפני התור ואחריו. המקום משרת בעיקר את תושבי השכונות הסמוכות, ותיירים מגיעים אליו בדרך כלל אגב ביקור בקניון.",
  "מספר המסלולים, המבצעים והמחירים המדויקים מופיעים באתר המקום. באולמות מסוג זה יש לרוב כדורים קלים ומעקות לילדים, ואפשר להזמין מסלול לימי הולדת. הקניון רחוק ממסלולי התיירות הרגילים, כ-25 דקות במטרו ממרכז העיר, ולכן הביקור משתלם בעיקר למי שמתכנן גם קניות.",
  ["הקניון נקרא על שם מפעל הקטרים והמכונות שפעל באותו מקום עד סוף המאה ה-20."],
  kd="באולינג", ag="6-25"),

