F("סנוקר וביליארד", "מועדון הסנוקר ז'ואניק", "Snooker Club Joanic", 41.40576, 2.16217, GRA,
  "מועדון סנוקר וביליארד שכונתי ברחוב ברוניקר, בחלקו המזרחי של רובע גרסיה. זהו מועדון ספורט ולא אולם בילוי, ולכן ייתכן שהמשחק מותנה בחברות או בתיאום מראש. מתאים בעיקר לשחקני סנוקר שמחפשים שולחן תקני בזמן השהות בעיר, ופחות למבקרים מזדמנים.",
  "שעות הפעילות אינן ידועות בוודאות, לרוב אחר הצהריים ובערב. כדאי לבדוק מול המועדון.",
  "התשלום בדרך כלל לפי שעת שולחן. המחירים אצל המועדון.",
  "לפני שמגיעים כדאי ליצור קשר ולברר אם אורחים שאינם חברים יכולים לשחק ובאילו שעות. במועדונים מסוג זה מקובל לשמור על שקט סביב השולחנות. מטרו L4 ז'ואניק, כמה דקות הליכה.",
  5.8, "Snooker Club Joanic Barcelona",
  "בספרד, ביליארד פירושו קודם כול קרמבולה, המשחק בשלושה כדורים על שולחן בלי כיסים, ובברים משחקים פול אמריקני. סנוקר, עם השולחן הירוק הענק ועשרים ושניים הכדורים, הוא ענף קטן הרבה יותר כאן, ומי שמשחק בו עושה זאת בדרך כלל במועדון ייעודי. מועדון הסנוקר ז'ואניק הוא אחד מהמקומות האלה.\n"
  "המועדון שוכן ברחוב צדדי ליד כיכר ז'ואניק, באזור מגורים של גרסיה שרחוק מעט מהכיכרות ההומות של הרובע. בנתוני המפה הוא רשום כמועדון ספורט לסנוקר ולביליארד. מקומות כאלה מתנהלים לרוב סביב קהילה של שחקנים קבועים, ליגות פנימיות ואימונים.",
  "מספר השולחנות, תנאי הכניסה לאורחים והמחירים אינם ידועים, ויש לברר אותם ישירות מול המועדון. שולחן סנוקר תקני גדול בהרבה משולחן פול, אורכו כ-3.6 מטר, ומי שרגיל לפול מגלה שהמשחק דורש דיוק רב יותר. מי שמחפש ביליארד קליל עם משקה ימצא בגרסיה ובשאר העיר ברים עם שולחנות פול.",
  ["אורכו של שולחן סנוקר תקני הוא כ-3.6 מטר, ארוך בהרבה משולחן פול רגיל."]),

F("סנוקר וביליארד", "בר ביליארד HDP", "Bar Billar HDP", 41.40178, 2.15507, GRA,
  "בר ביליארד בלב רובע גרסיה: שולחנות משחק, משקאות ואווירה של בילוי ערב שכונתי. מקום למשחק קליל בין חברים ולא לאימון מקצועי. הבר אינו כשר. מתאים למבוגרים ולצעירים שמטיילים בגרסיה בערב ורוצים לשלב משחק עם משקה.",
  "בדרך כלל משעות אחר הצהריים או הערב ועד הלילה. כדאי לבדוק באתר המקום.",
  "התשלום לפי משחק או לפי זמן שולחן, ובנוסף משקאות. המחירים באתר המקום.",
  "המקום הוא בר, ולכן בשעות הערב הכניסה מיועדת בדרך כלל למבוגרים; מי שמגיע עם בני נוער כדאי שיברר מראש. בערבי סוף השבוע ייתכן שצריך להמתין לשולחן. אינו כשר. מטרו L3 פונטנה, כמה דקות הליכה.",
  5.6, "Bar Billar HDP Gràcia Barcelona",
  "גרסיה הייתה עיירה נפרדת עד סוף המאה ה-19, ומשהו מהעצמאות הזאת נשאר בה: רחובות צרים, כיכרות קטנות שבהן יושבים עד מאוחר, ובעלי עסקים שמכירים את הלקוחות בשמם. חיי הלילה של הרובע מתנהלים בברים קטנים ולא במועדונים גדולים, ובכמה מהם עומד במרכז שולחן ביליארד.\n"
  "בר ביליארד HDP הוא מקום כזה. המשחק הנפוץ בברים של ברצלונה הוא פול, בגרסה האמריקנית או הבריטית, והכללים המקומיים נקבעים לא פעם בהסכמה בין השחקנים רגע לפני הפתיחה. מקובל שמי שרוצה לשחק מול המנצחים מניח מטבע על שפת השולחן ומחכה לתורו.",
  "מספר השולחנות, סוג המשחקים ושעות הפתיחה המדויקות מופיעים באתר המקום. הבר נמצא במרחק הליכה קצר מהכיכרות המרכזיות של גרסיה, ואפשר לשלב את הביקור בסיבוב ערב ברובע. באוגוסט, בשבוע חגיגות גרסיה, הרחובות שמסביב מקושטים והאזור כולו עמוס בהרבה מהרגיל.",
  ["גרסיה סופחה לברצלונה רק ב-1897, ועד אז הייתה עיירה עצמאית."]),

F("סנוקר וביליארד", "ל'אובייה נגרה מרינה", "L'Ovella Negra Marina", 41.39602, 2.19013, SM,
  "אולם בירה גדול מאוד במבנה תעשייתי ישן ברחוב סמורה, בין מרינה לפובלנואו. שולחנות עץ ארוכים, מסכים לשידורי ספורט, ולצדם שולחנות ביליארד וכדורגל שולחן. המקום אינו כשר. מתאים לקבוצות חברים ולצעירים; בשעות הערב הכניסה, ככל הנראה, מגיל 18.",
  "בדרך כלל משעות אחר הצהריים ועד אחרי חצות, ובסופי שבוע עד מאוחר יותר. כדאי לבדוק באתר המקום.",
  "אין דמי כניסה בדרך כלל; משלמים על משקאות ועל משחקי השולחן. המחירים באתר המקום.",
  "בערבים של משחקי כדורגל גדולים המקום מתמלא, וכדאי להגיע מוקדם. בערב הכניסה מיועדת, ככל הנראה, לבני 18 ומעלה, כדאי לברר מראש ולהביא תעודה מזהה. אינו כשר. מטרו L1 מרינה, כמה דקות הליכה.",
  6.6, "L'Ovella Negra Marina Barcelona",
  "הכבשה השחורה, זה פירוש השם בקטלאנית, התחילה כמסבאה ותיקה בסמטה ליד הרמבלה, שסטודנטים ותרמילאים פוקדים כבר עשרות שנים. הסניף של מרינה לקח את אותו רעיון והגדיל אותו פי כמה: מחסן תעשייתי שלם, תקרה גבוהה עם קורות חשופות, ושורות ארוכות של שולחנות וספסלי עץ שאליהם מתיישבות חבורות גדולות.\n"
  "המשקאות מוגשים, בין השאר, בכדים לשיתוף, ובין השולחנות פזורים שולחנות ביליארד וכדורגל שולחן שמעסיקים את מי שמחכה לחברים או לתחילת המשחק על המסך. בערבי כדורגל האולם הופך ליציע תוסס, וזו אחת הסיבות שרבים מגיעים אליו.",
  "המבנה שייך לנוף התעשייתי הישן של פובלנואו והסביבה, אזור של בתי מלאכה ומחסנים שרבים מהם הוסבו לשימושים חדשים. כמה דקות הליכה משם נמצאים מועדוני הלילה הגדולים של אזור מרינה, ורבים מתחילים כאן את הערב. מי שמעוניין בעיקר בביליארד כדאי שיגיע בשעה מוקדמת, כשהשולחנות פנויים יותר.",
  ["פירוש השם L'Ovella Negra בקטלאנית הוא הכבשה השחורה."]),

